input.command:
cd D:\pal
$checks = @()
$fe = -1; $aster = 0
try { $r = Invoke-WebRequest 'http://localhost:8080/' -UseBasicParsing -TimeoutSec 30; $fe = [int]$r.StatusCode; if ($r.Content -match 'Asterleaf') { $aster = 1 } } catch { $fe = -2 }
$checks += [pscustomobject]@{name='frontend_serves_200_with_asterleaf_company_rendered'; actual=($fe * 100 + $aster); expected=20001}
$h1 = ''; $h2 = ''
try { $h1 = [string](Invoke-RestMethod 'http://127.0.0.1:8082/health' -TimeoutSec 10).status } catch { $h1 = 'err' }
try { $h2 = [string](Invoke-RestMethod 'http://127.0.0.1:8082/api/v1/health' -TimeoutSec 10).status } catch { $h2 = 'err' }
$checks += [pscustomobject]@{name='backend_root_health_status_ok'; actual=$h1; expected='ok'}
$checks += [pscustomobject]@{name='backend_api_v1_health_status_ok'; actual=$h2; expected='ok'}
$body = (Invoke-WebRequest 'http://127.0.0.1:8082/api/v1/companies' -UseBasicParsing -TimeoutSec 20).Content
$names = ($body | ConvertFrom-Json).name
$n = if ($names -is [array]) { $names.Count } else { 1 }
$checks += [pscustomobject]@{name='db_companies_endpoint_returns_3_rows'; actual=$n; expected=3}
Push-Location backend
$cur = (.\.venv\Scripts\python.exe -m alembic current 2>&1 | Out-String)
$heads = (.\.venv\Scripts\python.exe -m alembic heads 2>&1 | Out-String)
Pop-Location
$curTag = 'unknown'; if ($cur -match '(0\d{3}_[a-z0-9_]+)') { $curTag = $matches[1] }
$headTag = 'unknown'; if ($heads -match '(0\d{3}_[a-z0-9_]+)') { $headTag = $matches[1] }
$checks += [pscustomobject]@{name='alembic_current_revision'; actual=$curTag; expected='0012_bank_tally_source'}
$checks += [pscustomobject]@{name='alembic_head_revision_is_ahead_of_current'; actual=$headTag; expected='0013_add_audit_entity_types'}
Write-Output ("detail cur=$curTag head=$headTag companies=$n fe=$fe")
$payload = [pscustomobject]@{version=1; checks=$checks}
Write-Output ('{"harnessVerification":' + (ConvertTo-Json -Compress -Depth 4 $payload) + '}')

